{
  "leaks": [
    {
      "source": "AUTH frame builder",
      "rva_or_symbol": "sub_100D93B0 (RVA 0x000D93B0)",
      "description": "Constructs 'AUTH:' + HwidBuilder() result and sends via sub_100DC080. Uses sub_101D3C30 (HwidBuilder) — currently JMP-redirected to code cave with fake HWID by patcher. AUTH frame receives spoofed value; no direct leak.",
      "severity": "low"
    },
    {
      "source": "HWID JSON assembler",
      "rva_or_symbol": "sub_101D3890 (RVA 0x001D3890)",
      "description": "Assembles v2:guid=...;smbios=...;volser=...;cpu=... by calling: (a) sub_101D3430 → HKLM\\SOFTWARE\\Microsoft\\Cryptography 'MachineGuid' via RegQueryValueExA, (b) sub_101D35C0 → GetSystemFirmwareTable('RSMB') SMBIOS UUID, (c) GetVolumeInformationA(WinDir) → volume serial, (d) inline CPUID eax=0/eax=1 → vendor+signature. Called ONLY from sub_101D3C30 (HwidBuilder), which patcher JMPs to cave — chain is bypassed. Sub_101D3890 has no other callers.",
      "severity": "low"
    },
    {
      "source": "MachineGuid registry lookup (raw)",
      "rva_or_symbol": "sub_101D3430 (RVA 0x001D3430)",
      "description": "Directly RegQueryValueExA(HKLM, 'SOFTWARE\\Microsoft\\Cryptography', 'MachineGuid'). Only xref = sub_101D3890 (HWID assembler). Since HwidBuilder JMPs to cave BEFORE calling this, MachineGuid is never read in patched build. UNPATCHED but unreachable via current JMP.",
